// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/settings/SecurityShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Settings → Security → Permissions, ported from the app's SetupSettings
 * (src/panels/SetupSettings.tsx) with the permission rows of SetupPermissions
 * (src/tour/SetupSteps.tsx, PERMISSIONS in src/state/permissions.ts): the
 * page's intro, its state and actions on top, then PzzaCode's five macOS
 * privacy permissions, three of them allowed.
 */
import { Accessibility, HardDrive, LockOpen, Mic, MonitorUp, RefreshCw, Workflow, type LucideIcon } from "lucide-react";
import { SettingsWindow } from "./SettingsWindow";
import { SetupRow, SmallButton, type Tone } from "./SetupParts";

type Status = "granted" | "notGranted";

const PERMISSION_PILLS: Record<Status, { tone: Tone; text: string }> = {
  granted: { tone: "ok", text: "Allowed" },
  notGranted: { tone: "action", text: "Not allowed" },
};

/** The app's permissions (subject "app"), each with its icon and one-line purpose. */
const PERMISSIONS: { id: string; icon: LucideIcon; label: string; short: string; status: Status }[] = [
  { id: "fullDiskAccess", icon: HardDrive, label: "Full Disk Access", short: "Read Desktop, Documents, Downloads and iCloud Drive", status: "granted" },
  { id: "microphone", icon: Mic, label: "Microphone", short: "Dictation and tools that record audio", status: "granted" },
  { id: "screenRecording", icon: MonitorUp, label: "Screen Recording", short: "Screenshots and screen capture from tools", status: "notGranted" },
  { id: "accessibility", icon: Accessibility, label: "Accessibility", short: "Tools that drive the keyboard, mouse and windows", status: "granted" },
  { id: "automation", icon: Workflow, label: "Automation", short: "AppleScript control of other apps", status: "notGranted" },
];

function PermissionsPage() {
  const allowed = PERMISSIONS.filter((item) => item.status === "granted").length;
  const pending = PERMISSIONS.length - allowed;
  return (
    <div className="settings-page setup-settings">
      <div className="setup-settings-intro">
        <p>The macOS privacy permissions PzzaCode needs. Every shell, agent and tool you start here runs as PzzaCode.</p>
        <div className="setup-settings-actions">
          <span className="setup-settings-state is-action" role="status">
            {allowed} of {PERMISSIONS.length} allowed
          </span>
          <SmallButton primary icon={LockOpen}>
            Allow all ({pending})
          </SmallButton>
          <button
            type="button"
            className="btn btn-sm"
            title="Choose sessions to refresh, or refresh all so every terminal gets new permissions. Output, folders and agent chats come back; programs running in them stop."
          >
            <RefreshCw size={13} aria-hidden="true" />
            Refresh sessions
          </button>
        </div>
      </div>
      <div className="setup-settings-page">
        <div className="tour-stack">
          <section className="tour-group" aria-label="PzzaCode permissions">
            <p className="tour-group-note">Every shell, agent and tool you start here runs as PzzaCode.</p>
            <ul className="tour-list">
              {PERMISSIONS.map(({ id, icon, label, short, status }) => (
                <SetupRow
                  key={id}
                  icon={icon}
                  label={label}
                  detail={short}
                  pill={PERMISSION_PILLS[status]}
                  action={
                    status === "granted" ? null : (
                      <SmallButton primary icon={LockOpen}>
                        Allow
                      </SmallButton>
                    )
                  }
                />
              ))}
            </ul>
          </section>
        </div>
      </div>
    </div>
  );
}

export function SecurityShot() {
  return (
    // Security's five pages make the nav taller than the dialog, with no scroll
    // position that shows it without cutting an entry, so the scene folds them
    // away as a click on the open section does; the page stays on Permissions.
    <SettingsWindow section="security" page="permissions" folded>
      <PermissionsPage />
    </SettingsWindow>
  );
}
